type Card = { cardNumber: string };
type Transfer = { bank: string; account: string };
type Wallet = { provider: string; phone: string };
type Payment = Card | Transfer | Wallet;

function describePayment(p: Payment): string {
  if ("cardNumber" in p) {
    const digits = p.cardNumber.replace(/\s/g, "");
    return `Kartu ****${digits.slice(-4)}`;
  }
  if ("bank" in p) {
    return `Transfer ${p.bank.toUpperCase()} ${p.account}`;
  }
  return `E-wallet ${p.provider}`;
}

